// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testRegression_property() public {
        vm.deal(address(this), 1 ether);

        c.initialize();

        vm.prank(address(0xdead));
        bool updateSucceeded = false;
        try c.updateAlloSettings(address(0x1234)) {
            updateSucceeded = true;
        } catch {
            updateSucceeded = false;
        }


        c = new RoundFactory();
        c.initialize();

        vm.prank(address(0xdead));
        try c.updateAlloSettings(address(0x1234)) {} catch {}

        vm.prank(address(0xdead));
        bytes memory emptyParams = abi.encode("");
        try c.create(emptyParams, address(0xdead)) {} catch {}

        address expectedReference = address(0);
        address actual = c.alloSettings();
        assertTrue(actual == expectedReference, "alloSettings should be zero in reference");
    }
}
